INSERT INTO tbl_climbing_shoes ( brand, model, foot_shape, foot_shape_spec, wall_size, pad_type, toe_box_size, heel_cup_size, heel_cup_hardness, main_uses, key_features ) VALUES
                                                                                                                                                                               ( '라 스포르티바', '솔루션 (Solution)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '중간', '하드(hard)', '볼더', '강력한 락 하네스 시스템으로 발을 고정하며, 단단한 힐컵으로 강한 힐훅을 지탱하는 전통의 상급자용 명기입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '솔루션 콤프 (Solution Comp)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '좁음', '소프트(soft)', '좁음', '작음', '미디엄(medium)', '복합', '기존 솔루션을 현대 실내 볼더링 트렌드에 맞춰 유연하게 개선한 모델입니다. 슬림해진 힐컵으로 세밀한 힐훅 감각을 제공합니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '띠어리 (Theory)', '그리스형', '비대칭 구조이면서도 토박스나 발볼에 여유가 있어 두 번째 발가락이 긴 그리스형 발에 적합하도록 설계되었습니다. 다양한 발 모양을 커버하는 복합형 성격을 띠지만 그리스형 특성을 우선하여 분류하였습니다.', '넓음', '소프트(soft)', '넓음', '중간', '소프트(soft)', '볼더', '노엣지(No-Edge) 기술이 적용되어 홀드와의 접촉 면적을 극대화합니다. 볼륨 홀드를 비벼 딛는 스미어링และ 다이내믹 무브에 최적화되어 있습니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '스콰마 (Skwama)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '중간', '하드(hard)', '복합', '발볼이 비교적 편하게 나왔으며, 앞창 중앙이 갈라진 솔 구조로 발가락 유연성이 뛰어납니다. 실내외 가리지 않는 최고의 전천후 모델입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '만다라 (Mandara)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '중간', '미디엄(medium)', '복합', '노엣지 기술을 벨크로 타입에 최적화하여 엣징과 스미어링의 경계를 허문 하이엔드 퍼포먼스 슈즈입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '미우라 (Miura)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '좁음', '하드(hard)', '좁음', '큼', '미디엄(medium)', '리드', '매우 단단한 중창 구조로 눈에 보이지 않는 미세한 바위 돌기를 정밀하게 딛고 설 수 있게 돕는 자연 바위 리드의 전설적인 모델입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '카타나 (Katana)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '하드(hard)', '좁음', '중간', '미디엄(medium)', '리드', '편안한 착착감과 안정적인 지지력을 동시에 제공하여 초중급자부터 상급자까지 리드 및 지구력 벽에서 신뢰하는 모델입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '카타나 레이스 (Katana Laces)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '하드(hard)', '좁음', '중간', '미디엄(medium)', '리드', 'P3 시스템이 적용되어 오랜 시간 착용해도 형태가 무너지지 않으며, 끈 묶음식 구조로 정밀한 피팅과 강력한 엣징을 자랑합니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '퓨추라 (Futura)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '중간', '미디엄(medium)', '복합', '노엣지 기술을 적용하여 길들이기 전에도 홀드에 완벽히 밀착되는 감각을 선사하는 고급 벨크로 암벽화입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '타란툴라 (Tarantula)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '하드(hard)', '중간', '큼', '미디엄(medium)', '복합', '발 통증이 거의 없는 편안한 컴포트 슈즈로, 고무창이 두껍고 단단하여 뛰어난 내구성을 자랑하는 국민 입문화입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '피날레 (Finale)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '하드(hard)', '좁음', '중간', '미디엄(medium)', '리드', '친환경 가죽을 사용한 끈식 모델로, 발을 편안하게 감싸주어 긴 시간 등반해야 하는 멀티피치나 지구력 연습에 최적입니다.' ),
                                                                                                                                                                               ( '라 스포르티바', '쿠보 (Kubo)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '중간', '미디엄(medium)', '복합', '입문을 벗어난 클라이머가 기량을 다지기에 적합하도록 성능과 편안함의 균형을 완벽하게 맞춘 웰메이드 모델입니다.' ),
                                                                                                                                                                               ( '파이브텐', '하이앵글 (Hiangle)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '좁음', '하드(hard)', '좁음', '작음', '하드(hard)', '복합', '수많은 대회와 올림픽에서 검증된 명작입니다. 스텔스(Stealth) HF/C4 고무창을 적용해 인공 홀드와 바위를 가리지 않는 사기적인 접지력을 보여줍니다.' ),
                                                                                                                                                                               ( '파이브텐', '니아드 VCS (NIAD VCS)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '하드(hard)', '좁음', '중간', '미디엄(medium)', '리드', '클래식 아나사지 라인업의 후속작으로, 짱짱하고 딱딱한 플랫 창을 기반으로 미세 엣징을 디딜 때 최고의 지지 성능을 발휘합니다.' ),
                                                                                                                                                                               ( '파이브텐', '니아드 Lace (NIAD Lace)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '하드(hard)', '좁음', '중간', '미디엄(medium)', '리드', '끈 결속 방식으로 발을 아주 정밀하게 묶어주며 중창이 매우 단단합니다. 슬래브, 페이스, 크랙 등반 등 전통적인 바위 등반의 강자입니다.' ),
                                                                                                                                                                               ( '파이브텐', '알레온 (Aleon)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '중간', '미디엄(medium)', '볼더', '전설적인 클라이머 프레드 니콜이 디자인에 참여했습니다. 양말 같은 니트 외피가 발등을 편안하게 감싸며 오버행에서 앞코로 홀드를 낚아채기 좋습니다.' ),
                                                                                                                                                                               ( '파이브텐', '키리가미 (Kirigami)', '로마형', '발가락 길이가 전반적으로 고른 대칭 형태를 띠어, 발볼 압박이 덜한 로마형 족형에 알맞습니다. 평평하고 일정한 공간 분배가 특징이므로 로마형으로 분류하였습니다.', '중간', '미디엄(medium)', '중간', '큼', '미디엄(medium)', '복합', '발 모양에 스트레스를 주지 않는 편안한 초급자용 신발입니다. 패딩 처리된 설포와 둥근 앞코 구조로 통증 없는 클라이밍을 지원합니다.' ),
                                                                                                                                                                               ( '테나야', '이아티 (Iati)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '작음', '미디엄(medium)', '복합', '오아시보다 가죽 비중을 높이고 약간 더 짱짱하게 세팅했습니다. 미세 엣징 능력이 뛰어나 자연 바위 크랙이나 페이스 등반에 아주 좋습니다.' ),
                                                                                                                                                                               ( '테나야', '오아시 (Oasi)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '작음', '미디엄(medium)', '복합', '테나야의 정체성인 "운동화 같은 편안함"을 보여주는 하이엔드 슈즈입니다. 정밀 벨크로로 고정되며 발 통증 없이 상급 성능을 냅니다.' ),
                                                                                                                                                                               ( '테나야', '오아시 LV (Oasi LV)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '좁음', '소프트(soft)', '좁음', '작음', '미디엄(medium)', '복합', '오아시의 성능과 편안함을 그대로 살리면서 족형을 칼발 및 좁은 뒤꿈치 형태로 축소하여 빈틈없는 핏을 연출합니다.' ),
                                                                                                                                                                               ( '테나야', '마스티아 (Mastia)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '중간', '미디엄(medium)', '복합', '테나야의 단점이었던 힐컵 밀착력을 완벽히 보강하여 출시된 볼더링 특화 슈즈입니다. 발볼이 넉넉해졌고 앞코 반발력이 좋습니다.' ),
                                                                                                                                                                               ( '테나야', '인달로 (Indalo)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '미디엄(medium)', '좁음', '중간', '미디엄(medium)', '볼더', '마스티아의 고성능 바닥 설계에 오아시의 정밀 특허 벨크로 시스템을 결합했습니다. 발을 진공 압착하듯 묶어 어려운 루프 문제를 풀 때 유용합니다.' ),
                                                                                                                                                                               ( '이볼브', '샤만 (Shaman)', '그리스형', '비대칭 구조이면서도 토박스나 발볼에 여유가 있어 두 번째 발가락이 긴 그리스형 발에 적합하도록 설계되었습니다. 다양한 발 모양을 커버하는 복합형 성격을 띠지만 그리스형 특성을 우선하여 분류하였습니다.', '넓음', '하드(hard)', '넓음', '큼', '미디엄(medium)', '복합', '크리스 샤마의 시그니처입니다. 엄지발가락 아래 공간을 확보하는 "러브 범프" 기술로, 강한 다운토임에도 발가락 고통이 적어 발볼러들에게 최고입니다.' ),
                                                                                                                                                                               ( '이볼브', '제니스트 (Zenist)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '중간', '소프트(soft)', '볼더', '유연성이 극대화된 초경량 암벽화입니다. 볼륨 홀드를 딛고 도약하거나 벽을 뛰고 비비는 현대 볼더링 스타일에 가장 알맞습니다.' ),
                                                                                                                                                                               ( '이볼브', '팬텀 (Phantom)', '이집트형', '엄지발가락 쪽으로 힘을 집중하기 유리한 강한 비대칭 구조와 좁은 토박스를 가지고 있어 전형적인 이집트형 족형에 적합합니다. 족형의 복합적인 특성이 존재할 수 있으나 이집트형 특성을 최우선으로 분류하였습니다.', '중간', '소프트(soft)', '좁음', '작음', '미디엄(medium)', '볼더', '이볼브 하이엔드 기술의 결정체로 아치를 받쳐주는 네오플렉스 기술이 들어가 부드러운 마찰력과 앞코 지지력의 완벽한 접점을 보여줍니다.' ),
